(window.TIMELINE_TRANSLATIONS=window.TIMELINE_TRANSLATIONS||{})["zh"]={"qin-dynasty":{"id":"qin-dynasty","title":"秦朝","summary":"秦国在嬴政领导下征服了主要对手，嬴政采用了“秦始皇”这一皇帝称号。秦朝存续时间很短，但其军事和行政做法影响了后来的汉朝。","began":"秦国的征战最终实现统一，嬴政自称皇帝。","ended":"秦始皇死后数年，秦朝崩溃；各方势力相互争斗，此后汉朝才建立起帝国统治。","why":"创立了后世王朝加以调整沿用的帝制政治框架。"},"confucius":{"id":"confucius","title":"孔子倡导德治","summary":"孔子在春秋时期讲学。他强调道德操守、家庭责任、学习，以及君主以德治国的职责。他的学说成为重要的思想传统，后来的帝制政府把儒家经典置于官方教育的核心。","why":"他的学说塑造了整个东亚的政治伦理、教育和家庭理想。"},"stonewall-riots":{"id":"stonewall-riots","title":"石墙起义","summary":"顾客和支持者在纽约石墙酒吧反抗警察突袭，随后又发生了更多冲突和示威。这场起义成为反对迫害性少数群体的日益壮大的运动的重要参照点。","why":"石墙推动了同性恋解放运动和后来的 LGBTQ 组织工作，但它并非第一次反抗行动。"}};
